WITH cc_agg AS ( SELECT cc.cc_call_center_sk, cc.cc_name, SUM(cr.cr_return_amount) AS total_return_amount, SUM(cr.cr_return_tax) AS total_return_tax, SUM(cr.cr_net_loss) AS total_net_loss, COUNT(*) AS return_count, AVG(cr.cr_return_quantity) AS avg_return_qty FROM catalog_returns cr JOIN call_center cc ON cr.cr_call_center_sk = cc.cc_call_center_sk GROUP BY cc.cc_call_center_sk, cc.cc_name ), cc_ranked AS ( SELECT cc_agg.*, RANK() OVER (ORDER BY total_return_amount DESC) AS return_amount_rank, CASE WHEN total_return_amount > 1000000 THEN 'Platinum' WHEN total_return_amount > 500000 THEN 'Gold' WHEN total_return_amount > 100000 THEN 'Silver' ELSE 'Bronze' END AS tier FROM cc_agg ) SELECT cc_call_center_sk, cc_name, total_return_amount, total_return_tax, total_net_loss, return_count, avg_return_qty, return_amount_rank, tier FROM cc_ranked ORDER BY return_amount_rank LIMIT 10
